PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE films (slug TEXT, title TEXT, year INTEGER, decade INTEGER, sort_title TEXT, runtime INTEGER, tmdb REAL, rt REAL, ebert REAL, revenue_real REAL, budget_real REAL, multiple REAL, poster TEXT, director_primary TEXT, first_episode TEXT, last_episode TEXT, episodes INTEGER, revisited INTEGER, plot TEXT, tmdb_id INTEGER, PRIMARY KEY (slug));
CREATE TABLE film_genres (slug TEXT, ord INTEGER, genre TEXT, PRIMARY KEY (slug, ord));
CREATE TABLE film_directors (slug TEXT, ord INTEGER, name TEXT, PRIMARY KEY (slug, ord));
CREATE TABLE film_cast (slug TEXT, billing INTEGER, name TEXT, PRIMARY KEY (slug, billing));
CREATE TABLE film_keywords (slug TEXT, word TEXT, PRIMARY KEY (slug, word));
CREATE TABLE episodes (id TEXT, slug TEXT, number INTEGER, date TEXT, is_revisit INTEGER, revisit_sequence INTEGER, revisit_type TEXT, verdict TEXT, rt REAL, ebert REAL, note TEXT, PRIMARY KEY (id));
CREATE TABLE episode_room (episode TEXT, person TEXT, chair TEXT, PRIMARY KEY (episode, person));
COMMIT;
